$ErrorActionPreference = "Stop"

$repoRoot = (Get-Location).Path
$packagePath = Join-Path $repoRoot "package.json"
$compilerDirectory = Join-Path $repoRoot "scripts\entity"
$compilerPath = Join-Path $compilerDirectory "build-evidence-packets.js"
$p03Output = Join-Path $repoRoot ".private\entity\build\P03"

$required = @(
  "package.json",
  ".private\entity\build\P01\entities.json",
  ".private\entity\build\P02\knowledge-index.json",
  ".private\see\build\RelationshipGraph\index.json",
  ".private\see\build\EventGraph\index.json",
  ".private\see\build\ThemeGraph\index.json"
)

foreach ($relativePath in $required) {
  $fullPath = Join-Path $repoRoot $relativePath
  if (-not (Test-Path $fullPath -PathType Leaf)) {
    throw "Run this installer from the ai-bible-app repository root. Missing: $relativePath"
  }
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $repoRoot ".private\backups\p03-evidence-packets-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

function Backup-Path([string]$RelativePath) {
  $source = Join-Path $repoRoot $RelativePath
  if (-not (Test-Path $source)) { return }

  $destination = Join-Path $backupRoot $RelativePath
  $destinationParent = Split-Path -Parent $destination
  if ($destinationParent) {
    New-Item -ItemType Directory -Force -Path $destinationParent | Out-Null
  }

  if ((Get-Item $source).PSIsContainer) {
    Copy-Item $source $destination -Recurse -Force
  } else {
    Copy-Item $source $destination -Force
  }
}

function Restore-Path([string]$RelativePath) {
  $backup = Join-Path $backupRoot $RelativePath
  $target = Join-Path $repoRoot $RelativePath

  if (Test-Path $target) {
    Remove-Item $target -Recurse -Force
  }

  if (-not (Test-Path $backup)) { return }

  $targetParent = Split-Path -Parent $target
  if ($targetParent) {
    New-Item -ItemType Directory -Force -Path $targetParent | Out-Null
  }

  if ((Get-Item $backup).PSIsContainer) {
    Copy-Item $backup $target -Recurse -Force
  } else {
    Copy-Item $backup $target -Force
  }
}

Backup-Path "scripts\entity\build-evidence-packets.js"
Backup-Path "package.json"
Backup-Path ".private\entity\build\P03"

