dGFjayA6IGVycm9yKTsKICBwcm9jZXNzLmV4aXRDb2RlID0gMTsKfQo=
'@

try {
  New-Item -ItemType Directory -Force -Path $compilerDirectory | Out-Null
  [System.IO.File]::WriteAllBytes(
    $compilerPath,
    [System.Convert]::FromBase64String(($compilerBase64 -replace "\s", ""))
  )

  node --check $compilerPath
  if ($LASTEXITCODE -ne 0) {
    throw "P03 compiler syntax validation failed."
  }

  $packageUpdater = @'
const fs = require("fs");

const packagePath = "package.json";
const pkg = JSON.parse(fs.readFileSync(packagePath, "utf8"));
pkg.scripts = pkg.scripts || {};

pkg.scripts["build:evidence-packets"] =
  "node --max-old-space-size=4096 scripts/entity/build-evidence-packets.js";
pkg.scripts["verify:evidence-packets"] =
  "node scripts/entity/build-evidence-packets.js --verify";
pkg.scripts["build:entity-platform"] =
  "npm run build:entity && npm run build:knowledge && npm run build:evidence-packets";

fs.writeFileSync(packagePath, `${JSON.stringify(pkg, null, 2)}\n`, "utf8");
'@

  $packageUpdater | node
  if ($LASTEXITCODE -ne 0) {
    throw "Unable to update package.json scripts."
  }

  Write-Host ""
  Write-Host "Installed complete P03 compiler:" -ForegroundColor Green
  Write-Host "  scripts\entity\build-evidence-packets.js"
  Write-Host ""
  Write-Host "Added npm scripts:"
  Write-Host "  npm run build:evidence-packets"
  Write-Host "  npm run verify:evidence-packets"
  Write-Host "  npm run build:entity-platform"
  Write-Host ""

  npm run build:evidence-packets
  if ($LASTEXITCODE -ne 0) {
    throw "P03 build failed. Review the compiler error above."
  }

  npm run verify:evidence-packets
  if ($LASTEXITCODE -ne 0) {
    throw "P03 verification failed."
  }

  Write-Host ""
  Write-Host "P03 installation, build, and verification complete." -ForegroundColor Green
  Write-Host ""
  Write-Host "Outputs:"
  Write-Host "  .private\entity\build\P03\evidence-packets.json"
  Write-Host "  .private\entity\build\P03\manifest.json"
  Write-Host "  .private\entity\build\P03\audit.json"
  Write-Host ""
  Write-Host "Backup:"
  Write-Host "  $backupRoot"
  Write-Host ""
  Write-Host "Audit summary command:"
  Write-Host '  node -e "const r=require(''./.private/entity/build/P03/audit.json''); console.log(JSON.stringify({totalPackets:r.totalPackets,packetsByCorpus:r.packetsByCorpus,availability:r.packetsByAvailabilityLevel,lexical:r.packetsWithLexicalEvidence,rendering:r.packetsWithRenderingEvidence,occurrence:r.packetsWithOccurrenceEvidence,chronology:r.packetsWithChronology,relationships:r.packetsWithRelationshipEvidence,events:r.packetsWithEventEvidence,themes:r.packetsWithThemeEvidence,missing:r.entitiesMissingPackets,extra:r.packetsMissingEntities,invalidP02:r.invalidP02References,dangling:r.danglingSeePointers,largest:r.largestPacket,averageBytes:r.averagePacketSizeBytes,coverage:r.corpusCoverage,invariants:r.invariants,samples:r.samples},null,2));"'
  Write-Host ""
  Write-Host "Next git commands:"
  Write-Host "  git status"
  Write-Host "  git add scripts/entity/build-evidence-packets.js package.json"
  Write-Host '  git commit -m "Add deterministic P03 EMET evidence packet compiler"'
  Write-Host "  git push origin HEAD"
} catch {
  Write-Host ""
  Write-Host "P03 installation failed. Restoring previous files..." -ForegroundColor Yellow

  Restore-Path "scripts\entity\build-evidence-packets.js"
  Restore-Path "package.json"
  Restore-Path ".private\entity\build\P03"

  throw
}
